-- ===========================================================================
-- Hand-written part (prisma/README.md: objects Prisma cannot express).
-- Phase 2 M1 lead records. Runs as crm_migrator. Adds policies and grants for the
-- new tables only; no existing policy, grant or role is changed.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Integrity (lead-lifecycle §4, domain-model §2.2)
-- ---------------------------------------------------------------------------
ALTER TABLE lead_source
  ADD CONSTRAINT lead_source_channel CHECK (channel IN
    ('PORTAL', 'SOCIAL_ADS', 'WEBSITE', 'REFERRAL', 'WALK_IN', 'CHANNEL_PARTNER', 'COLD', 'OTHER')),
  ADD CONSTRAINT lead_source_name_length CHECK (length(btrim(name)) BETWEEN 1 AND 100);
CREATE UNIQUE INDEX lead_source_org_name_uq ON lead_source (org_id, lower(name));

ALTER TABLE lead
  ADD CONSTRAINT lead_full_name_length CHECK (length(btrim(full_name)) BETWEEN 1 AND 200),
  ADD CONSTRAINT lead_primary_phone_e164 CHECK (primary_phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  ADD CONSTRAINT lead_alternate_phone_e164
    CHECK (alternate_phone_e164 IS NULL OR alternate_phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  ADD CONSTRAINT lead_alternate_phone_differs
    CHECK (alternate_phone_e164 IS DISTINCT FROM primary_phone_e164),
  ADD CONSTRAINT lead_phone_last10 CHECK (phone_last10 ~ '^[0-9]{1,10}$'),
  ADD CONSTRAINT lead_preferred_language CHECK (preferred_language IS NULL OR preferred_language ~ '^[a-z]{2}$'),
  ADD CONSTRAINT lead_preferred_contact_method
    CHECK (preferred_contact_method IS NULL OR preferred_contact_method IN ('PHONE', 'WHATSAPP', 'EMAIL', 'ANY')),
  ADD CONSTRAINT lead_transaction_type
    CHECK (transaction_type IS NULL OR transaction_type IN ('BUY', 'RENT', 'LEASE_COMMERCIAL', 'SELL', 'LET_OUT')),
  ADD CONSTRAINT lead_property_type CHECK (property_type IS NULL OR property_type IN
    ('APARTMENT', 'VILLA', 'PLOT', 'ROW_HOUSE', 'OFFICE', 'SHOP', 'WAREHOUSE', 'OTHER')),
  ADD CONSTRAINT lead_bhk_range CHECK (
    (bhk_min IS NULL OR bhk_min BETWEEN 0 AND 20) AND (bhk_max IS NULL OR bhk_max BETWEEN 0 AND 20)
    AND (bhk_min IS NULL OR bhk_max IS NULL OR bhk_min <= bhk_max)),
  ADD CONSTRAINT lead_budget_range CHECK (
    (budget_min IS NULL OR budget_min > 0) AND (budget_max IS NULL OR budget_max > 0)
    AND (budget_min IS NULL OR budget_max IS NULL OR budget_min <= budget_max)),
  ADD CONSTRAINT lead_purpose CHECK (purpose IS NULL OR purpose IN ('SELF_USE', 'INVESTMENT', 'UNKNOWN')),
  ADD CONSTRAINT lead_timeline CHECK (timeline IS NULL OR timeline IN
    ('IMMEDIATE', 'WITHIN_1M', '1_3M', '3_6M', '6M_PLUS', 'UNKNOWN')),
  ADD CONSTRAINT lead_intent CHECK (intent IS NULL OR intent IN ('HOT', 'WARM', 'COLD')),
  ADD CONSTRAINT lead_contact_status CHECK (contact_status IN ('OK', 'DO_NOT_CONTACT', 'INVALID')),
  ADD CONSTRAINT lead_localities_limit CHECK (cardinality(preferred_localities) <= 20),
  ADD CONSTRAINT lead_version_positive CHECK (version >= 1),
  ADD CONSTRAINT lead_not_own_predecessor CHECK (previous_lead_id IS DISTINCT FROM id),
  ADD CONSTRAINT lead_not_merged_into_self CHECK (merged_into_lead_id IS DISTINCT FROM id);

-- One open lead per phone per org (lead-lifecycle §5.5, domain-model §2.2). Concurrent
-- creates that pass the application check still cannot both commit.
CREATE UNIQUE INDEX lead_open_phone_uq ON lead (org_id, primary_phone_e164)
  WHERE stage NOT IN ('WON', 'LOST') AND deleted_at IS NULL AND merged_into_lead_id IS NULL;

ALTER TABLE lead_enquiry
  ADD CONSTRAINT lead_enquiry_campaign_length CHECK (campaign IS NULL OR length(campaign) <= 200);
CREATE UNIQUE INDEX lead_enquiry_external_uq ON lead_enquiry (org_id, source_id, external_id)
  WHERE external_id IS NOT NULL;

ALTER TABLE lead_note
  ADD CONSTRAINT lead_note_body_length CHECK (length(btrim(body)) BETWEEN 1 AND 5000),
  ADD CONSTRAINT lead_note_edit_window CHECK (edited_until > created_at);

ALTER TABLE lead_stage_history
  ADD CONSTRAINT lead_stage_history_source CHECK (source IN ('USER', 'SYSTEM_RULE', 'IMPORT', 'INTEGRATION')),
  ADD CONSTRAINT lead_stage_history_changes CHECK (from_stage IS DISTINCT FROM to_stage),
  ADD CONSTRAINT lead_stage_history_reason_length CHECK (reason_text IS NULL OR length(reason_text) <= 1000);

ALTER TABLE lead_activity
  ADD CONSTRAINT lead_activity_type CHECK (type IN ('CREATED', 'ENQUIRY', 'STAGE', 'NOTE', 'FIELD_CHANGED'));

-- ---------------------------------------------------------------------------
-- 2. RLS: ENABLE + FORCE, migrator maintenance, crm_app tenant isolation
--    (same policy text as 0002 §3 for the Phase 1 tenant tables)
-- ---------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'lead_source', 'lead', 'lead_enquiry', 'lead_note', 'lead_stage_history', 'lead_activity'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY maintenance ON %I FOR ALL TO crm_migrator USING (true) WITH CHECK (true)', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO crm_app '
      'USING (org_id = (SELECT app.current_org_id())) '
      'WITH CHECK (org_id = (SELECT app.current_org_id()))', t);
  END LOOP;
END $$;

-- Attribution cannot be forged: rows naming an acting user must name the session's user
-- (app.user_id, set by withTenant from the authenticated session). System actors (no user)
-- write NULL. History and timeline rows are stamped with the transaction time. RESTRICTIVE,
-- so these narrow tenant_isolation; they never widen it.
CREATE POLICY actor_is_session_user ON lead AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (created_by IS NOT DISTINCT FROM (SELECT app.current_user_id()));
CREATE POLICY actor_is_session_user ON lead_enquiry AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (created_by IS NOT DISTINCT FROM (SELECT app.current_user_id()));
CREATE POLICY actor_is_session_user ON lead_note AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (author_id = (SELECT app.current_user_id()));
CREATE POLICY actor_is_session_user ON lead_stage_history AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (changed_by IS NOT DISTINCT FROM (SELECT app.current_user_id()) AND occurred_at = now());
CREATE POLICY actor_is_session_user ON lead_activity AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (actor_id IS NOT DISTINCT FROM (SELECT app.current_user_id()) AND occurred_at = now());

-- FR-059: only the author edits a note, and only inside its edit window.
CREATE POLICY author_edit_window ON lead_note AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (author_id = (SELECT app.current_user_id()) AND edited_until > now())
  WITH CHECK (author_id = (SELECT app.current_user_id()) AND edited_until > now());

-- ---------------------------------------------------------------------------
-- 3. crm_app grants (minimum). No DELETE anywhere: history is append-only, and lead
--    archive/erasure are later, separately reviewed features. crm_auth and
--    crm_platform get nothing on these tables.
-- ---------------------------------------------------------------------------
GRANT SELECT, INSERT ON lead_source TO crm_app;
GRANT SELECT, INSERT ON lead TO crm_app;
-- Identity, tenant and creation columns are never updatable.
GRANT UPDATE (
  full_name, primary_phone_e164, primary_phone_raw, alternate_phone_e164, phone_last10, email,
  preferred_language, preferred_contact_method, transaction_type, property_type,
  bhk_min, bhk_max, budget_min, budget_max, preferred_city, preferred_localities,
  purpose, timeline, intent, campaign, owner_user_id, team_id, stage, contact_status,
  first_contacted_at, qualified_at, first_visit_scheduled_at, first_visit_completed_at,
  won_at, lost_at, version, updated_at
) ON lead TO crm_app;
GRANT SELECT, INSERT ON lead_enquiry TO crm_app;
GRANT SELECT, INSERT ON lead_note TO crm_app;
GRANT UPDATE (body, updated_at) ON lead_note TO crm_app;
-- Immutable history and timeline: append-only.
GRANT SELECT, INSERT ON lead_stage_history, lead_activity TO crm_app;
